import{_ as d,o as e,c as r,a4 as o}from"./chunks/framework.BMj-uaUw.js";const u=JSON.parse('{"title":"用户端 · uni-app 实战","description":"","frontmatter":{},"headers":[{"level":2,"title":"两个端，一套后端","slug":"两个端-一套后端","link":"#两个端-一套后端","children":[]},{"level":2,"title":"为什么不直接写个手机版网页","slug":"为什么不直接写个手机版网页","link":"#为什么不直接写个手机版网页","children":[]},{"level":2,"title":"技术选型","slug":"技术选型","link":"#技术选型","children":[{"level":3,"title":"一个必须提前说清的事实：两个端的版本不一样","slug":"一个必须提前说清的事实-两个端的版本不一样","link":"#一个必须提前说清的事实-两个端的版本不一样","children":[]}]},{"level":2,"title":"这一栏讲什么","slug":"这一栏讲什么","link":"#这一栏讲什么","children":[]},{"level":2,"title":"怎么跟着做","slug":"怎么跟着做","link":"#怎么跟着做","children":[]},{"level":2,"title":"你会得到什么","slug":"你会得到什么","link":"#你会得到什么","children":[]}],"relativePath":"mobile/index.md","filePath":"mobile/index.md","lastUpdated":1789500881000}'),a={name:"mobile/index.md"};function n(i,t,l,s,h,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="用户端-·-uni-app-实战" tabindex="-1">用户端 · uni-app 实战 <a class="header-anchor" href="#用户端-·-uni-app-实战" aria-label="Permalink to &quot;用户端 · uni-app 实战&quot;">​</a></h1><p>管理端做完之后，你会发现一个尴尬的事：组织者能在电脑上发布活动了，学生却还得打开电脑才能报名。</p><p><strong>这一栏补上另一半 —— 用手机报名的学生端。</strong></p><h2 id="两个端-一套后端" tabindex="-1">两个端，一套后端 <a class="header-anchor" href="#两个端-一套后端" aria-label="Permalink to &quot;两个端，一套后端&quot;">​</a></h2><p>校园活动服务平台有两个使用者，他们的处境完全不同。</p><table tabindex="0"><thead><tr><th></th><th>管理端</th><th>用户端</th></tr></thead><tbody><tr><td>用的人</td><td>学生干部、社团负责人、审核老师</td><td>全校学生</td></tr><tr><td>在哪用</td><td>电脑浏览器，坐在桌前</td><td>手机，随时随地</td></tr><tr><td>主要动作</td><td>发布、审核、排场次</td><td>看活动、报名、查结果</td></tr><tr><td>页面量</td><td>12 个</td><td>5 个</td></tr><tr><td>频次</td><td>一周几次</td><td>一天可能看几次</td></tr></tbody></table><p><strong>它们连的是同一个后端、同一套接口约定。</strong> 管理端的 <code>docs/project/api.md</code> 里的 <code>code</code> 约定、错误码、分页结构，用户端一条不改地沿用。</p><p>这一点决定了整件事的性质：<strong>这不是另起一个项目，而是同一个项目的第二个前端。</strong></p><h2 id="为什么不直接写个手机版网页" tabindex="-1">为什么不直接写个手机版网页 <a class="header-anchor" href="#为什么不直接写个手机版网页" aria-label="Permalink to &quot;为什么不直接写个手机版网页&quot;">​</a></h2><p>你也可以给管理端的样式加上媒体查询，让它在手机上勉强能看。但我们不做，有三个原因。</p><p><strong>原因一：学生要的不是“能看”，是“顺手”。</strong> 手指点的东西和鼠标点的不一样 —— 要更大的点击区、要能下拉刷新、要能滑动返回。这些在桌面端的框架里做出来很别扭。</p><p><strong>原因二：微信小程序才是学生真正会打开的入口。</strong> 让他们输网址、登录、收藏，大部分人不会做第二次；扫码或从微信里点开一个小程序，门槛低得多。</p><p><strong>原因三：一套代码要能出多端。</strong> 用 uni-app 写的这份代码，同一套可以编译成 H5（浏览器直接开）、微信小程序（扫码就用）、App（打包上架）。<strong>这才是这一栏要教的核心能力：一套代码，多端运行，以及多端之间那些不能共用的部分到底有哪些。</strong></p><h2 id="技术选型" tabindex="-1">技术选型 <a class="header-anchor" href="#技术选型" aria-label="Permalink to &quot;技术选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>选型</th><th>版本</th></tr></thead><tbody><tr><td>跨端框架</td><td>uni-app（Vue 3 版）</td><td>编译器 3.0.0-5020420260813003</td></tr><tr><td>构建</td><td>Vite（由 uni-app 编译器锁定）</td><td>5.2.8</td></tr><tr><td>框架</td><td>Vue</td><td>3.4.21</td></tr><tr><td>UI 组件库</td><td>Wot UI（<code>@wot-ui/ui</code>）</td><td>2.3.2</td></tr><tr><td>样式</td><td>sass</td><td>1.104.1</td></tr><tr><td>包管理</td><td>pnpm</td><td>12.4.1</td></tr></tbody></table><h3 id="一个必须提前说清的事实-两个端的版本不一样" tabindex="-1">一个必须提前说清的事实：两个端的版本不一样 <a class="header-anchor" href="#一个必须提前说清的事实-两个端的版本不一样" aria-label="Permalink to &quot;一个必须提前说清的事实：两个端的版本不一样&quot;">​</a></h3><p>这是学生第一次对照教程时最容易懵的地方：</p><table tabindex="0"><thead><tr><th>项</th><th>管理端</th><th>用户端</th><th>为什么</th></tr></thead><tbody><tr><td>Vite</td><td>8.3.0</td><td>5.2.8</td><td>uni-app 的编译器自己锁定了 Vite 版本，你改不了</td></tr><tr><td>Vue</td><td>3.5.42</td><td>3.4.21</td><td>同上，跟着编译器走</td></tr><tr><td>路由</td><td>Vue Router 5</td><td><code>pages.json</code> 配置</td><td>小程序没有浏览器 history，路由必须是配置式的</td></tr><tr><td>UI 库</td><td>Element Plus</td><td>Wot UI</td><td>Element Plus 是桌面组件，手机上点不动</td></tr><tr><td>请求</td><td>axios</td><td><code>uni.request</code></td><td>小程序没有 XMLHttpRequest，axios 跑不起来</td></tr><tr><td>样式单位</td><td>px</td><td>rpx</td><td>手机屏幕宽度差异大，需要一个相对单位</td></tr></tbody></table><p><strong>看到 Vite 5.2.8 不要以为教程写错了。</strong> uni-app 是一层编译器，它把 Vue 代码翻译成各个小程序平台能跑的代码，为了兼容十几个平台，它必须锁住一套经过验证的依赖版本。<strong>这是跨端框架的固有代价，不是配置失误。</strong></p><p>顺带说一个实际影响：<strong>你在管理端学到的 Vite 配置技巧，在用户端有一半用不上。</strong> 比如 <code>vite.config.js</code> 里能改的东西少得多，很多东西要写在 <code>manifest.json</code> 和 <code>pages.json</code> 里。</p><h2 id="这一栏讲什么" tabindex="-1">这一栏讲什么 <a class="header-anchor" href="#这一栏讲什么" aria-label="Permalink to &quot;这一栏讲什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>篇</th><th>标题</th><th>解决什么问题</th></tr></thead><tbody><tr><td>1</td><td><a href="/frontend-engineering-course/mobile/01-why-uniapp.html">为什么是 uni-app</a></td><td>它和 Web 版 Vue 差在哪，和 uni-app x 又差在哪</td></tr><tr><td>2</td><td><a href="/frontend-engineering-course/mobile/02-scaffold.html">建工程：从命令到跑起来</a></td><td>建项目、装组件库、在浏览器和微信开发者工具里跑起来</td></tr><tr><td>3</td><td><a href="/frontend-engineering-course/mobile/03-pages-router.html">页面与路由</a></td><td>没有 Vue Router 之后，页面怎么注册、怎么跳、怎么传参</td></tr><tr><td>4</td><td><a href="/frontend-engineering-course/mobile/04-layout-style.html">布局与样式</a></td><td>rpx、flex、安全区、条件编译</td></tr><tr><td>5</td><td><a href="/frontend-engineering-course/mobile/05-components.html">组件与组件库</a></td><td>easycom 机制、Wot UI 常用组件、表单校验</td></tr><tr><td>6</td><td><a href="/frontend-engineering-course/mobile/06-request-auth.html">请求封装与登录态</a></td><td>把 <code>uni.request</code> 包成和管理端一样好用的东西</td></tr><tr><td>7</td><td><a href="/frontend-engineering-course/mobile/07-list-detail.html">列表页与详情页</a></td><td>下拉刷新、触底加载、四态在手机上的写法</td></tr><tr><td>8</td><td><a href="/frontend-engineering-course/mobile/08-signup-form.html">报名表单与我的报名</a></td><td>表单校验、提交、状态展示、取消报名</td></tr><tr><td>9</td><td><a href="/frontend-engineering-course/mobile/09-publish.html">打包与发布</a></td><td>H5 部署上线、小程序上传体验版</td></tr><tr><td>10</td><td><a href="/frontend-engineering-course/mobile/10-ai-collaboration.html">AI 协作</a></td><td>AI 写 uni-app 代码时最容易错的地方</td></tr></tbody></table><h2 id="怎么跟着做" tabindex="-1">怎么跟着做 <a class="header-anchor" href="#怎么跟着做" aria-label="Permalink to &quot;怎么跟着做&quot;">​</a></h2><p><strong>前置条件：</strong> 完成管理端，或者至少学完单元 10。理由很实在 —— 请求层怎么设计、状态的四种情况怎么分、错误码怎么用，这些在用户端一模一样要用一遍。<strong>管理端没做过就做用户端，等于同时学两件新东西。</strong></p><p><strong>建议用时：</strong> 12 到 16 小时。其中建工程和请求层大约占一半 —— 这两块做完，剩下的页面基本是重复劳动。</p><p><strong>不占课内学时。</strong> 48 学时的正课安排不变，这一栏是给学有余力的小组做的第二个端，也适合作为答辩时的加分项。</p><div class="tip custom-block"><p class="custom-block-title">先看一眼成品再动手</p><p>第 2 篇讲完就能跑起来一个空白页。<strong>不要等到全部读完才动手</strong>，边读边做，每篇末尾的检查点都过一遍再往下走。</p></div><h2 id="你会得到什么" tabindex="-1">你会得到什么 <a class="header-anchor" href="#你会得到什么" aria-label="Permalink to &quot;你会得到什么&quot;">​</a></h2><p>做完这一栏，你应该能：</p><ul><li>用命令行建一个 uni-app 工程，并说清 <code>pages.json</code>、<code>manifest.json</code>、<code>uni.scss</code> 三个文件各管什么</li><li>一套代码同时跑在浏览器和微信开发者工具里，并说出哪些写法只在某一个平台上有效</li><li>用 Wot UI 的组件拼出列表页、详情页、表单页，说明 easycom 为什么不用手写 import</li><li>把 <code>uni.request</code> 封装成带统一鉴权、统一错误处理、Promise 化的请求层</li><li>处理移动端特有的状态：下拉刷新、触底加载、返回时重新拉数据</li><li>把 H5 版本部署到服务器，把小程序版本上传成体验版</li></ul><p>下一步：<a href="/frontend-engineering-course/mobile/01-why-uniapp.html">为什么是 uni-app</a>。</p>',31)])])}const g=d(a,[["render",n]]);export{u as __pageData,g as default};
